// Pure helpers for bundle reports: which package a bundled file belongs to,
// and how many generated bytes a source map attributes to each source. No I/O.

const BACKSLASH = String.fromCharCode(92);

/** `npm:<package>`, `src:<area>` or `other` for a path from a metafile or a source map. */
export function bucketOfPath(path) {
  const p = path.split(BACKSLASH).join("/");
  const i = p.lastIndexOf("node_modules/");
  if (i >= 0) {
    const rest = p.slice(i + "node_modules/".length).split("/");
    return (
      "npm:" + (rest[0].startsWith("@") ? `${rest[0]}/${rest[1]}` : rest[0])
    );
  }
  const m = p.match(
    /(?:^|\/)(packages\/[^/]+|core|extensions\/[^/]+|gui|src)\//,
  );
  return m ? `src:${m[1]}` : "other";
}

/** Adds `bytes` to `totals[key]`. Returns `totals`. */
export function addTo(totals, key, bytes) {
  totals[key] = (totals[key] ?? 0) + bytes;
  return totals;
}

/** Bytes in the output per bucket for one output of an esbuild metafile. */
export function bucketsOfMetafileOutput(output) {
  const totals = {};
  for (const [input, v] of Object.entries(output.inputs ?? {})) {
    addTo(totals, bucketOfPath(input), v.bytesInOutput);
  }
  return totals;
}

const B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

/**
 * Generated characters per source index, from a source map's `mappings` and
 * the length of each generated line. A segment owns the columns up to the
 * next segment (or the end of its line); segments without a source own none.
 * Returns a Map of source index to characters.
 */
export function charsPerSource(mappings, lineLengths) {
  const out = new Map();
  let line = 0;
  let pos = 0;
  let source = 0;
  let column = 0;
  let previousColumn = -1;
  let previousSource = -1;
  const flush = (until) => {
    if (previousSource >= 0 && previousColumn >= 0 && until > previousColumn) {
      out.set(
        previousSource,
        (out.get(previousSource) ?? 0) + (until - previousColumn),
      );
    }
  };
  while (pos <= mappings.length) {
    const ch = mappings[pos];
    if (ch === ";" || pos === mappings.length) {
      flush(lineLengths[line] ?? 0);
      line++;
      column = 0;
      previousColumn = -1;
      previousSource = -1;
      pos++;
      continue;
    }
    if (ch === ",") {
      pos++;
      continue;
    }
    const fields = [];
    while (
      pos < mappings.length &&
      mappings[pos] !== "," &&
      mappings[pos] !== ";"
    ) {
      let shift = 0;
      let value = 0;
      let digit;
      do {
        digit = B64.indexOf(mappings[pos++]);
        if (digit < 0) throw new Error("not a base64 VLQ digit");
        value += (digit & 31) << shift;
        shift += 5;
      } while (digit & 32);
      fields.push(value & 1 ? -(value >> 1) : value >> 1);
    }
    column += fields[0];
    flush(column);
    if (fields.length >= 4) {
      source += fields[1];
      previousSource = source;
    } else {
      previousSource = -1;
    }
    previousColumn = column;
  }
  return out;
}

/** The largest `top` entries of a totals object, as `[key, bytes]`, largest first. */
export function topEntries(totals, top = 30) {
  return Object.entries(totals)
    .sort((a, b) => b[1] - a[1])
    .slice(0, top);
}
